<script>
import { defineComponent, ref, computed, onMounted } from "vue";
import { userStore } from "stores/index";
import {
  RiWalletLine,
  RiBankCardLine,
  RiShieldFlashLine,
  RiUser5Line,
  RiBankLine,
  RiMailLine,
  RiVipCrown2Line,
  RiLogoutBoxLine
} from "vue-remix-icons";

export default defineComponent({
  name: "AccountPage",
  components: {
    RiWalletLine,
    RiBankCardLine,
    RiShieldFlashLine,
    RiUser5Line,
    RiBankLine,
    RiMailLine,
    RiVipCrown2Line,
    RiLogoutBoxLine
  },
  setup() {
    const store = userStore();
    const logout = () => {
      store.memberLogout().then(() => {
        location.reload();
      });
    };
    
    const vip = computed(() => {
      return store.vip;
    });
    
    const mainWallet = computed(() => {
      return store.currency.value + ' ' + store.balance;
    });
    onMounted(() => {
      getBalance()
      store.getBalance()
    });
    
    const getBalance = () => {
        setInterval(function(){ if (store.hasToken()) { store.getBalance() } }, 20000);
    }
    return {
      header: "บัญชี",
      logout,
      mainWallet,
      getBalance,
      vip
    };
  }
});
</script>
